import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var archived = React.useState(false), setArchived = archived[1];
    var favorite = React.useState(false), setFavorite = favorite[1];
    var message = React.useState('Объект доступен для работы.'), setMessage = message[1];
    return <div className="dsmenu-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <p>
    {'Volvo FH16' + (favorite[0] ? ' · В избранном' : '') + (archived[0] ? ' · В архиве' : '')}
    </p>
    <div className={'stage'}>
    <S.DsMenu width={'auto'} trigger={<S.DsIconButton icon={'more_vert'} label={'Действия с Volvo FH16'}/>} items={[
            { id: 'favorite', icon: favorite[0] ? 'star' : 'star_border', label: favorite[0] ? 'Убрать из избранного' : 'Добавить в избранное', onClick: function () { setFavorite(!favorite[0]); setMessage(favorite[0] ? 'Объект убран из избранного.' : 'Объект добавлен в избранное.'); } },
            { id: 'refresh', icon: 'refresh', label: 'Обновить данные', onClick: function () { setMessage('Данные объекта обновлены.'); } },
            { id: 'report', icon: 'description', label: 'Создать отчёт', disabled: true },
            { divider: true },
            { id: 'archive', icon: archived[0] ? 'unarchive' : 'archive', label: archived[0] ? 'Вернуть из архива' : 'В архив', tone: archived[0] ? 'default' : 'danger', onClick: function () { setArchived(!archived[0]); setMessage(archived[0] ? 'Объект возвращён из архива.' : 'Объект перемещён в архив.'); } }
        ]}/>
    </div>
    <p role={'status'} aria-label={'Результат действия'}>
    {message[0]}
    </p>
    <p className={'cap'}>
    {'Создание отчёта недоступно: у объекта пока нет истории поездок.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsmenu-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsmenu-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsmenu-example p{margin:0}\n.dsmenu-example .stage{padding-bottom:240px;display:flex;align-items:flex-start}\n.dsmenu-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted)}";

export { App as Example };

