import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var period = React.useState('day'), setPeriod = period[1];
    var periods = [{ id: 'day', label: 'Сегодня' }, { id: 'week', label: 'За неделю' }, { id: 'month', label: 'За месяц' }];
    return <div className="dsmenu-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'stage end'}>
    <S.DsMenu align={'end'} width={220} trigger={<S.DsButton tone={'secondary'} icon={'expand_more'}>
    {'Период'}
    </S.DsButton>} header={<span>
    {'Период отчёта'}
    </span>} footer={<span className={'cap'}>
    {'Время местное'}
    </span>} items={periods.map(function (item) { return Object.assign({}, item, { type: 'radio', checked: item.id === period[0] }); })} onSelect={function (item) { setPeriod(item.id); }}/>
    </div>
    <p role={'status'} aria-label={'Выбранный период'}>
    {'Период: ' + periods.find(function (item) { return item.id === period[0]; }).label + '.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsmenu-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsmenu-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsmenu-example p{margin:0}\n.dsmenu-example .stage{padding-bottom:240px;display:flex;align-items:flex-start}\n.dsmenu-example .end{justify-content:flex-end;padding-bottom:184px}\n.dsmenu-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted)}";

export { App as Example };

