import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var layers = React.useState(['objects']), setLayers = layers[1];
    var layerOptions = [{ id: 'objects', label: 'Объекты' }, { id: 'tracks', label: 'Треки' }, { id: 'zones', label: 'Геозоны' }];
    return <div className="dsmenu-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'stage controlled'}>
    <S.DsMenu menuLabel={'Слои карты'} width={220} trigger={<S.DsButton tone={'secondary'} icon={'layers'}>
    {'Слои'}
    </S.DsButton>} items={layerOptions.map(function (item) { return Object.assign({}, item, { type: 'checkbox', checked: layers[0].includes(item.id) }); })} onSelect={function (item) { setLayers(function (value) { return value.includes(item.id) ? value.filter(function (id) { return id !== item.id; }) : value.concat(item.id); }); }}/>
    </div>
    <p role={'status'} aria-label={'Видимые слои'}>
    {'Показаны: ' + (layerOptions.filter(function (item) { return layers[0].includes(item.id); }).map(function (item) { return item.label; }).join(', ') || 'нет слоёв') + '.'}
    </p>
    <p className={'cap'}>
    {'Можно выбрать несколько пунктов. Escape закрывает меню.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsmenu-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsmenu-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsmenu-example p{margin:0}\n.dsmenu-example .stage{padding-bottom:240px;display:flex;align-items:flex-start}\n.dsmenu-example .controlled{padding-bottom:144px}\n.dsmenu-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted)}";

export { App as Example };

